// v5.10.x strings (token-aware budgeting, backend retry, self-test, deployment presets, escalation consent, privacy).
$string['settings:backend_context_tokens'] = 'Fereastra de context a backendului (tokeni)';
$string['settings:backend_context_tokens_desc'] = 'Lungimea maximă de context (max_model_len) a backendului dvs. de IA, în tokeni. Setați la 0 pentru modele găzduite cu o fereastră mare (fără limitare). Când este setat peste 0 (de exemplu 8192 pe un backend vLLM auto-găzduit), [[tutorshort]] reduce bugetul de caractere al promptului de sistem de mai sus, astfel încât promptul plus ieșirea rezervată și istoricul conversației să încapă în fereastră, chiar și în limbi cu densitate mare de tokeni. Consultați pagina wiki Deployment Sizing pentru a vedea cum se corelează acest lucru cu numărul de utilizatori simultani.';
$string['settings:backend_retry_attempts'] = 'Încercări de reîncercare a backendului';
$string['settings:backend_retry_attempts_desc'] = 'De câte ori să se reîncerce o eroare tranzitorie a backendului (HTTP 429 sau 503) înainte de a afișa o eroare studentului. Reîncercările au loc doar înainte ca vreun text de răspuns să fie transmis, deci ieșirea nu este niciodată duplicată. Destinat backendurilor mici auto-găzduite care resping cererile sub sarcină. Setați la 0 pentru a dezactiva. Implicit 2.';
$string['settings:backend_retry_max_wait'] = 'Timp maxim de așteptare pentru reîncercarea backendului (secunde)';
$string['settings:backend_retry_max_wait_desc'] = 'Limita superioară, în secunde, a duratei de respectare a unui antet Retry-After de la backend înainte de reîncercare. Când backendul nu trimite Retry-After, [[tutorshort]] folosește în schimb o scurtă temporizare exponențială. Implicit 5.';
$string['prompt:truncation_hint'] = 'NOTĂ: Conținutul complet al cursului nu a putut fi căutat în această tură din cauza limitelor de lungime. Dacă studentul întreabă despre ceva ce nu puteți găsi în conținutul furnizat, spuneți că nu ați putut căuta întregul curs și sugerați-i să deschidă pagina sau activitatea specifică unde este tratat subiectul, în loc să afirmați că acesta lipsește din curs.';
