$string['settings:mastery_classifier_provider'] = 'Furnizor clasificator';
$string['settings:mastery_classifier_provider_desc'] = 'ID-ul furnizorului utilizat pentru clasificatorul de stăpânire per tur. Lăsați necompletat pentru a moșteni furnizorul AI implicit. Implicit <code>openai</code> pereche cu modelul clasificatorului <code>gpt-4o-mini</code> de mai jos — cea mai ieftină opțiune TIER 1 pentru clasificare cu ieșire structurată (~$220/lună economii la 100k MAU față de nivelul chat). Când este setat, rândul din Furnizori de comparație cu acest ID de furnizor furnizează cheia API, URL-ul de bază și temperatura.';
$string['settings:premium_escalation_heading'] = 'Nivel de escaladare premium (A.10)';
$string['settings:premium_escalation_heading_desc'] = 'Rutare opțională per tur către un model premium (Claude Opus 4.8 implicit) pentru prompt-uri cu care nivelul de chat de lucru se luptă vizibil — de obicei matematică cu mai mulți pași, CS și raționament științific. Rezolvat de bake-off-ul A.10 din 2026-06-09: Opus 4.8 a câștigat cu 14,97/15 față de 12,68/15 ale gpt-4o pe prompt-uri dificile. Două căi de declanșare: potriviri regex pe mesajul utilizatorului SAU o listă de permisiuni de curs care escaladează fiecare tur. Dezactivat implicit. La ~5% escaladare, așteptați ~$700/lună la 100k [[unishort]] MAU pe lângă cheltuielile de bază cu chat-ul.';
$string['settings:premium_escalation_enabled'] = 'Activați rutarea escaladării premium';
$string['settings:premium_escalation_enabled_desc'] = 'Când este activat, routerul per tur verifică lista de regex-uri declanșatoare și lista de permisiuni de curs pentru fiecare apel de chat; tururile corespunzătoare sunt rutate către furnizorul premium. Revine la furnizorul de lucru dacă rândul premium lipsește sau nu poate fi instanțiat. Suprascrierile selectorului de LLM al administratorului câștigă întotdeauna indiferent.';
$string['settings:premium_escalation_provider'] = 'Furnizor premium';
$string['settings:premium_escalation_provider_desc'] = 'ID-ul furnizorului prin care să rutați apelurile premium. Trebuie să corespundă unui rând din Furnizori de comparație (astfel încât cheia API, URL-ul de bază și temperatura să vină din același loc pe care administratorii îl gestionează deja). Implicit <code>claude</code>.';
$string['settings:premium_escalation_model'] = 'Model premium';
$string['settings:premium_escalation_model_desc'] = 'Numele modelului transmis furnizorului premium. Implicit <code>claude-sonnet-5</code> conform verdictului bake-off-ului A.10.';
$string['settings:premium_escalation_triggers'] = 'Regex-uri declanșatoare premium';
$string['settings:premium_escalation_triggers_desc'] = 'Un regex PCRE pe linie (fără delimitatori; potrivirea insensibilă la majuscule este aplicată automat). Liniile care încep cu # sunt comentarii. Lăsați necompletat pentru a utiliza setul implicit organizat din bake-off-ul A.10 (markeri STEM cu mai mulți pași: „derive", „prove that", „step by step", matematică LaTeX, blocuri de cod delimitate, big-O, integrale, optimizare, etc.).';
$string['settings:premium_escalation_course_tags'] = 'Lista de permisiuni cursuri premium';
$string['settings:premium_escalation_course_tags_desc'] = 'Un prefix de nume scurt sau idnumber de curs pe linie. Fiecare tur dintr-un curs corespunzător este escalat automat indiferent de regex-ul mesajului (utilizați pentru cursuri intensive STEM unde escaladarea ar trebui să fie implicită). Potrivirea este prefix insensibil la majuscule — „MATH" corespunde MATH121, MATH205, etc.';
$string['settings:spend_cap_per_course_default'] = 'Limită implicită de cheltuieli per curs (USD)';
$string['settings:spend_cap_per_course_default_desc'] = 'Limită defensivă aplicată fiecărui curs care nu are configurată propria limită de cheltuieli per curs. Setați la de ex. <code>30</code> pentru a limita cheltuielile lunare ale oricărui curs la $30 fără a ajusta cursurile individuale. <code>0</code> = nicio limită implicită (se aplică doar limitele la nivel de site și suprascrierile per curs). Când un curs depășește 80% / 95% / 100% din această limită, pipeline-ul existent de alerte spend-guard trimite notificarea administratorului (lista destinatarilor: <code>spend_notify_emails</code>, cu fallback la administratorii site-ului). Un curs specific poate întotdeauna ridica propriul plafon setând o suprascriere per curs mai mare.';
$string['settings:cost_anomaly_heading'] = 'Detector de anomalii de cost (v6.0)';
$string['settings:cost_anomaly_heading_desc'] = 'Sarcina programată zilnică (<code>cost_anomaly_check</code>) care compară cheltuielile [[tutorshort]] la nivel de site de astăzi cu mediana pe 7 zile. Trimite e-mail listei de destinatari <code>spend_notify_emails</code> (cu fallback la administratorii site-ului) când astăzi depășește multiplicatorul configurat × mediana. Detectează trei moduri de eșec pe care pragurile existente de 80% / 95% / 100% ale limitei de cheltuieli le ratează: (1) curs scăpat de sub control unde plafonul absolut nu este depășit, dar un singur curs generează brusc de 10x volumul său obișnuit, (2) activare accidentală a nivelului premium, (3) rutare greșită a furnizorului. Dezactivat implicit; echivalentul intern [[tutorshort]] al interogării Redash la <code>.drafts/sola-redash-cost-anomaly-2026-06-09.md</code>.';
$string['settings:cost_anomaly_enabled'] = 'Activați detectorul de anomalii de cost';
$string['settings:cost_anomaly_enabled_desc'] = 'Când este activat, sarcina programată zilnică evaluează cheltuielile de astăzi față de mediana pe 7 zile și trimite e-mail administratorilor la anomalie. Primele 7 zile după activare produc un status <code>insufficient_history</code> (încă fără bază de date istorică) și nu emit niciodată o alertă. Idempotent per zi: un flag în <code>config_plugins</code> oprește e-mailurile repetate dacă cron rulează de mai multe ori.';
$string['settings:cost_anomaly_multiplier'] = 'Multiplicator de anomalie';
$string['settings:cost_anomaly_multiplier_desc'] = 'Cheltuielile de astăzi trebuie să depășească acest multiplicator × mediana pe 7 zile pentru a declanșa o alertă. Implicit <code>2.0</code>. Reduceți la <code>1.5</code> pentru avertismente mai timpurii (mai multe fals pozitive în perioadele de înregistrare mare). Ridicați la <code>3.0</code> dacă utilizarea [[unishort]] este suficient de în rafale încât vârfurile de 2x să fie de rutină.';
$string['task:cost_anomaly_check'] = 'Verificare zilnică anomalii cost [[tutorshort]]';

