$string['settings:bench_default_samples'] = 'Prompturi pe rulare';
$string['settings:bench_default_samples_desc'] = 'Câte prompturi trimite un benchmark pus în coadă din interfața web. Fiecare prompt costă două apeluri reale către model — răspunsul și judecătorul — deci acesta este butonul de cost. Limitat la 50 în cod, ceea ce reprezintă atât dimensiunea setului golden, cât și limita care menține o rulare în cadrul limitei de rată a furnizorului.';
$string['settings:bench_heading'] = 'Benchmarkuri de modele';
$string['settings:bench_heading_desc'] = 'O rulare de benchmark răspunde la 50 de prompturi și pune un model-judecător să puncteze fiecare răspuns după o rubrică, apoi stochează un singur rând: media rubricii, costul pe apel și timpul până la primul octet. Rulările sunt puse în coadă din pagina registrului de modele și executate de cron.';
$string['settings:bench_judge_model'] = 'Model judecător';
$string['settings:bench_judge_model_desc'] = 'Modelul care punctează răspunsurile. Schimbarea lui schimbă sensul tuturor scorurilor obținute ulterior, motiv pentru care fiecare rulare consemnează judecătorul folosit și versiunea pluginului pe care a rulat.';
$string['settings:bench_judge_provider'] = 'Furnizorul judecătorului';
$string['settings:bench_judge_provider_desc'] = 'Furnizorul modelului care punctează răspunsurile. Țineți-l în afara grupului de concurenți: un model nu trebuie să se noteze pe sine.';
$string['settings:bench_min_quality_n'] = 'Prag minim de comparabilitate (elemente punctate)';
$string['settings:bench_min_quality_n_desc'] = 'Numărul minim de elemente punctate pe care o rulare stocată îl poate avea și totuși să fie comparată cu altă rulare. Rulările sub prag sunt păstrate și afișate, etichetate doar ca referință, astfel încât o rulare smoke cu trei prompturi să nu poată depăși niciodată un rezultat obținut pe cincizeci de prompturi. Lăsați 0 pentru a folosi valoarea implicită integrată; un prag de 0 ar anula protecția.';
$string['settings:embed_input_type_asymmetric'] = 'Interogare/document asimetrice';
$string['settings:embed_input_type_mode'] = 'Tipul de intrare pentru încorporare';
$string['settings:embed_input_type_mode_desc'] = 'Doar pentru încorporările Voyage. "Spațiu partajat" încorporează interogările și documentele în același mod, astfel încât cele două rămân comparabile după o schimbare de model. "Asimetric" folosește proiecția separată pentru interogări a Voyage; este optimizarea sugerată de furnizor, dar nu a reușit de două ori să reproducă vreun câștig pe acest corpus, deci spațiul partajat este valoarea implicită. Schimbarea acestei setări nu necesită o reindexare.';
$string['settings:embed_input_type_shared'] = 'Spațiu partajat (recomandat)';
$string['settings:embed_migration_heading'] = 'Migrarea modelului de încorporare';
$string['settings:embed_migration_heading_desc'] = 'Schimbarea modelului de încorporare sau a lățimii sale invalidează fiecare vector stocat: sistemul de regăsire refuză să puncteze o interogare față de fragmente din alt spațiu de încorporare, deci un curs nu regăsește nimic, în loc să regăsească prost. Aceste setări descriu modelul SPRE care migrați. Cursurile sunt apoi reîncorporate unul câte unul din pagina indexului RAG, scriind vectorii noi alături de cei vechi, iar setările active de mai sus continuă să deservească regăsirea până când le schimbați dumneavoastră.';
$string['settings:embed_migration_provider_inherit'] = 'Folosește furnizorul configurat mai sus';
$string['settings:embed_migration_target_apikey'] = 'Cheia API a furnizorului țintă';
$string['settings:embed_migration_target_apikey_desc'] = 'Necesară doar când furnizorul țintă diferă de cel configurat mai sus. Necompletat înseamnă folosirea cheii de încorporare existente.';
$string['settings:embed_migration_target_dimensions'] = 'Lățimea de încorporare țintă';
$string['settings:embed_migration_target_dimensions_desc'] = 'Lățimea vectorului solicitată în timpul migrării. 0 înseamnă lățimea nativă a modelului. Voyage acceptă 256, 512, 1024 și 2048; o lățime pe care modelul nu o oferă este omisă din cerere în loc să fie trimisă, ceea ce v-ar da în mod silențios lățimea nativă în locul celei cerute.';
$string['settings:embed_migration_target_model'] = 'Modelul de încorporare țintă';
$string['settings:embed_migration_target_model_desc'] = 'Numele modelului cu care se face încorporarea în timpul migrării, de exemplu <code>voyage-4-large</code>. Necompletat înseamnă că nu este configurată nicio migrare, iar pagina indexului RAG nu oferă niciuna.';
$string['settings:embed_migration_target_provider'] = 'Furnizorul de încorporare țintă';
$string['settings:embed_migration_target_provider_desc'] = 'Lăsați necompletat pentru a migra în cadrul furnizorului deja configurat mai sus.';
$string['settings:rerank_min_query_chars'] = 'Reordonare: lungimea minimă a interogării';
$string['settings:rerank_min_query_chars_desc'] = 'Omite re-rankerul pentru interogările cu acest număr de caractere sau mai puține. Interogările scurte au formă de cuvinte-cheie, iar re-rankerul adaugă aproape nimic peste similaritatea cosinus pe două sau trei cuvinte. Măsurat pe setul de fixtures RAG: limitarea la 50 a obținut 67,7 % acoperire față de 67,2 % pentru varianta mereu activă, la aproximativ o treime din cost. Setați 0 pentru a reordona fiecare interogare. Reordonările omise sunt consemnate în jurnalul de mesaje ca "[Rerank skipped: short_query]", ca să puteți confirma că limitarea funcționează.';
$string['settings:spend_export_key'] = 'Cheie pentru exportul cheltuielilor';
$string['settings:spend_export_key_desc'] = 'Cheie bearer pentru endpoint-ul lunar de export al cheltuielilor AI de la <code>/local/ai_course_assistant/spend_export.php</code>, pe care tabloul de bord al cheltuielilor îl interoghează o dată pe lună. Lăsați necompletat pentru a dezactiva endpoint-ul — acesta returnează apoi 404 la orice cerere. Cheia este acceptată DOAR într-un antet <code>Authorization: Bearer</code>, niciodată în URL. Generați o valoare lungă și aleatorie; oricine o deține poate citi cheltuielile AI ale întregului site. Fiecare export reușit este consemnat în jurnalul de audit al pluginului.';
